package org.researchdock.mobile;
import android.app.*;
import android.os.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.UUID;
import java.util.concurrent.*;

/** Private evidence-first research; all model execution stays on the Mac. */
public class ResearchActivity extends Activity {
 private final int INK=Color.rgb(32,44,42),GREEN=Color.rgb(36,107,83),BG=Color.rgb(246,245,240),MUTED=Color.rgb(101,115,108);
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());
 private MobileApi api;private LinearLayout content,history;private ScrollView scroll;private TextView state;private EditText question,target;private Spinner kind,days;private Button submit;
 private String taskId="",parentId="",pendingId="",pendingBody="",lastReport="";private boolean foreground=false,busy=false,submitting=false,hasPending=false;private int generation=0;private JSONObject current;
 private final Runnable poll=new Runnable(){public void run(){if(!foreground)return;if(hasPending)refresh();handler.postDelayed(this,6000);}};
 @Override public void onCreate(Bundle saved){super.onCreate(saved);api=new MobileApi(this);if(saved!=null)parentId=saved.getString("parent","");home();if(saved!=null){question.setText(saved.getString("question",""));target.setText(saved.getString("target",""));kind.setSelection(saved.getInt("kind",0));days.setSelection(saved.getInt("days",0));if(!saved.getString("task","").isEmpty())openTask(saved.getString("task"));}}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextColor(color);v.setTextSize(size);v.setLineSpacing(dp(3),1.1f);v.setPadding(0,dp(6),0,dp(6));return v;}
 private TextView heading(String value){TextView v=text(value,24,GREEN);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
 private Button button(String value,Runnable action){Button b=new Button(this);b.setText(value);b.setTextColor(GREEN);b.setTextSize(14);b.setAllCaps(false);b.setOnClickListener(v->action.run());return b;}
 private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private LinearLayout card(){LinearLayout l=column();l.setPadding(dp(14),dp(10),dp(14),dp(12));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(14));g.setStroke(dp(1),Color.rgb(219,228,220));l.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(7));content.addView(l,p);return l;}
 private void shell(String title){generation++;LinearLayout root=column();root.setBackgroundColor(BG);root.setFocusableInTouchMode(true);root.setPadding(dp(16),dp(8),dp(16),dp(8));setContentView(root);root.requestFocus();getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(button("‹ 返回",()->onBackPressed()));TextView h=heading(title);top.addView(h,new LinearLayout.LayoutParams(0,-2,1));top.addView(button("刷新",()->refresh()));root.addView(top);scroll=new ScrollView(this);scroll.setFillViewport(true);content=column();scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));state=text("",12,MUTED);root.addView(state);}
 private Spinner choices(String[] labels){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));return s;}
 private void home(){taskId="";lastReport="";shell("AI 调研");
  LinearLayout intro=card();intro.addView(text("从已有资料，形成有出处的判断",18,GREEN));intro.addView(text("检索归档正文及已缓存财务数据，由 Mac 调用 DeepSeek 整理。仅发送相关摘录；PDF、图片和音频不自动解析。",13,MUTED));
  LinearLayout form=card();if(!parentId.isEmpty())form.addView(text("追问当前报告 · 会重新检索最新资料",14,GREEN));
  question=new EditText(this);question.setHint("例如：近30天半导体行业需求有哪些变化和风险？");question.setMinLines(3);question.setMaxLines(6);question.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(600)});question.setTag("research:question");form.addView(question);
  target=new EditText(this);target.setHint("调研对象（可选）：公司名、代码或行业");target.setSingleLine(true);target.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(100)});form.addView(target);
  kind=choices(new String[]{"自动识别对象","公司调研","行业调研"});days=choices(new String[]{"从问题识别时间，默认30天","最近7天","最近30天","最近90天","最近365天"});form.addView(kind);form.addView(days);
  if(!parentId.isEmpty()&&current!=null){JSONObject r=current.optJSONObject("report");if(r!=null){target.setText(r.optString("target"));kind.setSelection("industry".equals(r.optString("kind"))?2:1);}}
  else if(getIntent().hasExtra("target")){target.setText(getIntent().getStringExtra("target"));kind.setSelection("industry".equals(getIntent().getStringExtra("kind"))?2:1);}
  submit=button("开始调研",()->submit());submit.setTag("research:submit");form.addView(submit);form.addView(text("所有设备共享每日额度。Mac 离线时任务排队，已有报告可离线阅读。AI 研判请结合原文核对。",12,MUTED));
  content.addView(heading("调研记录"));history=column();content.addView(history);JSONObject cached=cacheRead("research-history.json");if(cached!=null)renderHistory(cached,true);refresh();
 }
 private void renderHistory(JSONObject data,boolean offline){if(!taskId.isEmpty()||history==null)return;history.removeAllViews();JSONObject cfg=data.optJSONObject("config");if(cfg!=null){String note=cfg.optBoolean("enabled")?"已启用 · 每日最多 "+cfg.optInt("daily_limit")+" 个任务（设备共享）":"Mac 尚未启用调研执行器";history.addView(text(note,12,MUTED));String stamp=cfg.optString("worker_at");boolean stale=true;try{stale=java.time.Duration.between(java.time.OffsetDateTime.parse(stamp).toInstant(),java.time.Instant.now()).getSeconds()>90;}catch(Exception ignored){}if(stale)history.addView(text("执行器未在线：新任务将等待 Mac 恢复连接。",12,Color.rgb(145,91,29)));}
  JSONArray tasks=data.optJSONArray("tasks");hasPending=false;if(tasks!=null)for(int n=0;n<tasks.length();n++){JSONObject t=tasks.optJSONObject(n);if(t!=null&&("queued".equals(t.optString("status"))||"running".equals(t.optString("status"))))hasPending=true;}if(tasks==null||tasks.length()==0)history.addView(text("还没有调研报告，输入一个问题开始。",14,MUTED));else for(int i=0;i<tasks.length();i++){JSONObject t=tasks.optJSONObject(i);if(t==null)continue;String id=t.optString("id");Button b=button(t.optString("question")+"\n"+statusName(t.optString("status"))+" · "+shortDate(t.optString("created_at")),()->openTask(id));b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);history.addView(b,new LinearLayout.LayoutParams(-1,-2));}
  state.setText(offline?"离线缓存 · 连接后可刷新":"调研记录已更新");
 }
 private static String shortDate(String s){return s.length()>16?s.substring(0,16).replace('T',' '):s;}
 private static String statusName(String s){switch(s){case "queued":return "等待 Mac 执行";case "running":return "检索与生成中";case "completed":return "报告已完成";case "no_evidence":return "缺少可用原文";case "needs_input":return "需要明确调研对象";default:return "任务未完成";}}
 private void submit(){if(submitting)return;String q=question.getText().toString().trim();if(q.length()<2){question.setError("请输入至少两个字的调研问题");return;}try{JSONObject body=new JSONObject().put("question",q).put("target",target.getText().toString().trim()).put("kind",new String[]{"auto","company","industry"}[kind.getSelectedItemPosition()]).put("days",new int[]{0,7,30,90,365}[days.getSelectedItemPosition()]).put("parent_id",parentId);String signature=body.toString();JSONObject pending=cacheRead("research-pending.json");if(pending!=null&&signature.equals(pending.optString("body"))){pendingBody=signature;pendingId=pending.optString("id");}if(!signature.equals(pendingBody)||!pendingId.matches("[a-f0-9]{32}")){pendingBody=signature;pendingId=UUID.randomUUID().toString().replace("-","");}cacheWrite("research-pending.json",new JSONObject().put("body",pendingBody).put("id",pendingId));body.put("request_id",pendingId);submit.setEnabled(false);state.setText("正在提交；网络重试会保留同一任务编号");int g=generation;submitting=true;
   worker.execute(()->{try{JSONObject result=api.request("POST","/v1/research/tasks",body);ui(g,()->{submitting=false;new File(getFilesDir(),"research-pending.json").delete();pendingBody="";pendingId="";openTask(result.optString("id"));});}catch(Exception e){ui(g,()->{submitting=false;submit.setEnabled(true);state.setText(safeError(e));});}});
  }catch(JSONException e){state.setText("请检查调研问题");}}
 private void openTask(String id){if(!id.matches("[a-f0-9]{32}"))return;taskId=id;lastReport="";shell("调研报告");JSONObject cached=cacheRead("research-"+id+".json");if(cached!=null)renderReport(cached,true);else state.setText("正在读取报告…");refresh();}
 private void refresh(){if(busy||submitting||!api.configured())return;busy=true;final int g=generation;final String id=taskId;worker.execute(()->{try{JSONObject data=api.request("GET",id.isEmpty()?"/v1/research/tasks":"/v1/research/tasks/"+id,null);cacheWrite(id.isEmpty()?"research-history.json":"research-"+id+".json",data);runOnUiThread(()->{busy=false;if(g!=generation||isFinishing())return;if(id.isEmpty())renderHistory(data,false);else renderReport(data,false);});}catch(Exception e){runOnUiThread(()->{busy=false;if(g==generation&&!isFinishing())state.setText(safeError(e)+" · 已保存报告仍可阅读");});}});}
 private String safeError(Exception e){if(e instanceof IOException&&e.getMessage()!=null&&e.getMessage().length()<330&&!e.getMessage().contains("https://"))return e.getMessage();return "连接未完成，请检查网络后刷新";}
 private void ui(int g,Runnable action){runOnUiThread(()->{if(g==generation&&!isFinishing())action.run();else submitting=false;});}
 private void renderReport(JSONObject task,boolean offline){current=task;String signature=task.toString();if(signature.equals(lastReport)){state.setText(offline?"离线报告":"报告已同步");return;}lastReport=signature;int y=scroll.getScrollY();content.removeAllViews();content.addView(heading(task.optString("question")));String status=task.optString("status");hasPending="queued".equals(status)||"running".equals(status);content.addView(text(statusName(status)+" · "+shortDate(task.optString("created_at")),13,GREEN));if(!task.optString("message").isEmpty())content.addView(text(task.optString("message"),14,MUTED));JSONObject report=task.optJSONObject("report");
  if(report!=null){LinearLayout scope=card();scope.addView(text(report.optString("target")+" · "+("industry".equals(report.optString("kind"))?"行业":"公司")+" · "+report.optInt("days")+"天",17,GREEN));scope.addView(text("检索期间 "+shortDate(report.optString("range_start"))+" 至 "+shortDate(report.optString("range_end"))+"\n最新入选正文 "+shortDate(report.optString("as_of")),12,MUTED));JSONObject counts=report.optJSONObject("scope");if(counts!=null){scope.addView(text("入选 "+counts.optInt("selected_documents")+" 篇正文 / 匹配 "+counts.optInt("matched_documents")+" 篇\n未解析附件 "+counts.optInt("attachment_documents")+" · 日期不明排除 "+counts.optInt("unknown_dates")+" · 重复正文去重 "+counts.optInt("duplicate_documents")+(counts.optBoolean("financial_cache")?"\n包含已有缓存财务报表":""),13,MUTED));if(counts.optBoolean("truncated"))scope.addView(text("为控制费用，仅选取相关正文摘录，报告不代表全部资料。",12,Color.rgb(145,91,29)));}scope.addView(text(report.optString("model")+(report.optBoolean("reused")?" · 复用相同证据报告，未重复调用模型":"")+"\n生成于 "+shortDate(report.optString("generated_at")),12,MUTED));
   if(report.optInt("omitted_uncited_items")>0)scope.addView(text("有 "+report.optInt("omitted_uncited_items")+" 条模型内容缺少引用，已省略，未作为报告结论。",12,Color.rgb(145,91,29)));
   JSONArray sections=report.optJSONArray("sections");if(sections!=null)for(int i=0;i<sections.length();i++){JSONObject section=sections.optJSONObject(i);if(section==null)continue;LinearLayout block=card();new ResearchText(this,16,(p,id,caption)->p.addView(text("图片附件请查看原资料",12,MUTED))).render(block,"## "+section.optString("title"));JSONArray rows=section.optJSONArray("items");if(rows==null)continue;for(int j=0;j<rows.length();j++){JSONObject row=rows.optJSONObject(j);if(row==null)continue;new ResearchText(this,16,(p,id,caption)->{}).render(block,row.optString("text"));JSONArray cites=row.optJSONArray("citations");if(cites!=null){LinearLayout links=new LinearLayout(this);links.setOrientation(LinearLayout.VERTICAL);for(int k=0;k<cites.length();k++){String cite=cites.optString(k);JSONObject evidence=findEvidence(report,cite);if(evidence!=null){Button b=button("["+cite+"] "+evidence.optString("title"),()->showEvidence(evidence));b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);links.addView(b);}}block.addView(links);}}}
   if("completed".equals(status))content.addView(button("继续追问",()->{parentId=taskId;home();}));
  }
  content.addView(text("AI 综合研判需要核对原文；不同来源的分歧不等于同一机构观点变化。",12,MUTED));content.addView(button("新建调研",()->{parentId="";home();}));scroll.post(()->scroll.scrollTo(0,y));state.setText(offline?"离线报告":"queued".equals(status)||"running".equals(status)?"任务在 Mac 执行，可离开页面，稍后查看":"报告已同步");
 }
 private JSONObject findEvidence(JSONObject report,String id){JSONArray e=report.optJSONArray("evidence");if(e!=null)for(int i=0;i<e.length();i++){JSONObject x=e.optJSONObject(i);if(x!=null&&id.equals(x.optString("id")))return x;}return null;}
 private void showEvidence(JSONObject evidence){LinearLayout box=column();box.setPadding(dp(18),dp(10),dp(18),dp(16));ScrollView view=new ScrollView(this);view.addView(box);box.addView(heading(evidence.optString("title")));box.addView(text(evidence.optString("source_name")+" · "+shortDate(evidence.optString("published_at"))+" · 原文修订 r"+evidence.optInt("revision"),12,MUTED));box.addView(text("报告生成时保留的原文摘录",14,GREEN));TextView quote=text(evidence.optString("quote"),16,INK);quote.setTextIsSelectable(true);box.addView(quote);AlertDialog dialog=new AlertDialog.Builder(this).setView(view).setPositiveButton("返回报告",null).create();
  String id=evidence.optString("document_id");if(id.matches("doc_[0-9A-Z]{26}")){Button source=button("查看当前归档正文",()->{});source.setOnClickListener(v->{source.setEnabled(false);source.setText("正在读取正文…");worker.execute(()->{try{JSONObject doc=api.request("GET","/v1/documents/"+id,null);cacheWrite("research-source-"+id+".json",doc);runOnUiThread(()->{if(dialog.isShowing())renderSource(box,source,doc,evidence);});}catch(Exception e){JSONObject cached=cacheRead("research-source-"+id+".json");runOnUiThread(()->{if(!dialog.isShowing())return;if(cached!=null)renderSource(box,source,cached,evidence);else{source.setText(safeError(e));source.setEnabled(true);}});}});});box.addView(source);}dialog.show();}
 private void renderSource(LinearLayout box,Button source,JSONObject doc,JSONObject evidence){source.setVisibility(View.GONE);int revision=doc.optInt("revision");box.addView(text(revision==evidence.optInt("revision")?"当前归档正文 · r"+revision:"原文已更新至 r"+revision+"；上方引句保留报告当时 r"+evidence.optInt("revision")+" 的内容。",13,GREEN));new ResearchText(this,16,(p,id,caption)->p.addView(text("图片请在原资料阅读器查看",12,MUTED))).renderAsync(box,doc.optString("body"),()->!isFinishing(),()->{});}
 private JSONObject cacheRead(String name){try(FileInputStream in=openFileInput(name)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>2_000_000)return null;out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}catch(Exception e){return null;}}
 private void cacheWrite(String name,JSONObject value){try{File temp=new File(getFilesDir(),name+".tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(value.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!temp.renameTo(new File(getFilesDir(),name)))temp.delete();}catch(IOException ignored){}}
 @Override public void onBackPressed(){if(!taskId.isEmpty()){parentId="";home();}else super.onBackPressed();}
 @Override protected void onResume(){super.onResume();foreground=true;handler.postDelayed(poll,6000);}
 @Override protected void onPause(){foreground=false;handler.removeCallbacks(poll);super.onPause();}
 @Override protected void onSaveInstanceState(Bundle out){out.putString("task",taskId);out.putString("parent",parentId);if(question!=null){out.putString("question",question.getText().toString());out.putString("target",target.getText().toString());out.putInt("kind",kind.getSelectedItemPosition());out.putInt("days",days.getSelectedItemPosition());}super.onSaveInstanceState(out);}
 @Override protected void onDestroy(){generation++;handler.removeCallbacks(poll);worker.shutdownNow();super.onDestroy();}
}
